 void catalog(LinearLayout target,String type,String genre){
  final int ticket=epoch;final String key="cinema.catalog."+type+"."+genre;
  if(target.getChildCount()==0){target.addView(text("正在读取影片信息…",12,muted()));target.addView(Skeleton.row(this,card(),false,4));}
  job(()->{CacheFiles files=CacheFiles.of(this);JSONArray cache=null;String raw=files.readMigrating(this,key);try{if(raw!=null&&!raw.isEmpty())cache=new JSONArray(raw);}catch(Exception ignored){}boolean fresh=cache!=null&&cache.length()>0&&files.fresh(key,System.currentTimeMillis(),6L*60*60*1000L);
   if(cache!=null&&cache.length()>0){JSONArray shown=cache;runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;target.removeAllViews();shelf(target,shown,type,false);chooseHero(shown,type,genre);});if(fresh)return;}
   try{JSONArray items=CinemaCatalogClient.json("https://v3-cinemeta.strem.io/catalog/"+type+"/top"+(genre.isEmpty()?"":"/genre="+Net.esc(genre))+".json").optJSONArray("metas");if(items==null||items.length()==0)throw new IllegalStateException("empty catalog");files.write(key,items.toString());runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;target.removeAllViews();shelf(target,items,type,false);chooseHero(items,type,genre);});}catch(Exception e){runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;Skeleton.clear(target);if(target.getChildCount()==1&&target.getChildAt(0) instanceof TextView){TextView message=(TextView)target.getChildAt(0);message.setText("目录暂时无法读取 · 点此重试");message.setOnClickListener(v->catalog(target,type,genre));}});}});
 }
