 void fusionShelf(LinearLayout target,FusionCatalog.Session s,JSONObject c,int ticket,boolean lead){String category=c.optString("type_id"),key=FusionCatalog.cacheKey(s,category);target.addView(text("正在读取真实条目…",12,muted()));target.addView(Skeleton.row(this,card(),false,4));
  FusionCatalog.IO.execute(()->{if(ticket!=epoch)return;CacheFiles files=CacheFiles.of(this);JSONArray cached=null;String raw=files.readMigrating(this,key);try{if(raw!=null&&!raw.isEmpty())cached=new JSONArray(raw);}catch(Exception ignored){}boolean fresh=cached!=null&&cached.length()>0&&files.fresh(key,System.currentTimeMillis(),AggregateRules.FRESH_MS);
   if(cached!=null&&cached.length()>0){JSONArray shown=cached;runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;target.removeAllViews();if(lead)offerHeroes(shown,"movie",3);shelf(target,shown,"movie",false);});if(fresh)return;}
   try{JSONObject r=FusionCatalog.request(this,s,"category",category,"",1);JSONArray items=FusionCatalog.normalize(s,r.optJSONArray("list"),category);if(items.length()==0)throw new Exception("此分类暂无条目");files.write(key,items.toString());runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;target.removeAllViews();if(lead)offerHeroes(items,"movie",3);shelf(target,items,"movie",false);});}catch(Exception e){runOnUiThread(()->{if(ticket!=epoch||isFinishing())return;Skeleton.clear(target);if(target.getChildCount()==1&&target.getChildAt(0) instanceof TextView){TextView note=(TextView)target.getChildAt(0);note.setText("目录暂未返回 · 点此重试");note.setOnClickListener(v->fusionShelf(target,s,c,ticket,lead));}});}});
 }
 void chooseFusionSite(){if(fusionSession==null)return;JSONArray sites=fusionSession.config.optJSONArray("sites");java.util.ArrayList<JSONObject> candidates=new java.util.ArrayList<>();java.util.ArrayList<String> names=new java.util.ArrayList<>();for(int i=0;sites!=null&&i<sites.length();i++){JSONObject s=sites.optJSONObject(i);if(s==null||s.optInt("type",3)!=3)continue;candidates.add(s);names.add(s.optString("name")+(s.optString("api").equals("csp_AListSh")?" · 小雅样本已验证":" · 待实播验证"));}new AlertDialog.Builder(this).setTitle("影视仓首页来源").setItems(names.toArray(new String[0]),(d,n)->{prefs.edit().putString("fusion.site:"+fusionSession.url,candidates.get(n).optString("key")).apply();home();}).show();}
 void refreshFusion(){if(fusionSession==null){home();return;}String prefix="fusion.catalog.v3:"+fusionSession.url+"|"+fusionSession.site.optString("key")+"|";String homeKey="fusion.home:"+fusionSession.url+"|"+fusionSession.site.optString("key");job(()->{CacheFiles files=CacheFiles.of(this);files.removePrefix(prefix);files.remove(homeKey);runOnUiThread(()->{if(!isFinishing())home();});});}


 void recolor(View view){if(view instanceof TextView){TextView t=(TextView)view;int c=t.getCurrentTextColor();if(map(c)!=c)t.setTextColor(map(c));}Drawable d=view.getBackground();if(d instanceof ColorDrawable){int c=((ColorDrawable)d).getColor();if(map(c)!=c)((ColorDrawable)d).setColor(map(c));}else if(d instanceof GradientDrawable){ColorStateList c=((GradientDrawable)d).getColor();if(c!=null&&map(c.getDefaultColor())!=c.getDefaultColor())((GradientDrawable)d).setColor(map(c.getDefaultColor()));}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)recolor(((ViewGroup)view).getChildAt(i));}
 @Override protected void onResume(){keepHome=HomeRules.keepOnResume(homeCanvas,body==null?0:body.getChildCount());PlaybackOrientation.releaseHost(this);super.onResume();keepHome=false;resumed=true;if(body!=null)Skeleton.resume(body);Object[] next=AutoNext.consume();if(next!=null){final Object[] n=next;scroll.post(()->{if(isFinishing())return;if(EmbyPlayback.openNext(this,n))return;selectSource((String)n[0],(String)n[1],(JSONObject)n[2],true);});}if(homeCanvas&&prefs.getString("home.source.v1","fty").equals("current")&&fusionSession!=null&&!fusionSession.url.equals(prefs.getString("tvbox.active",fusionSession.url))){fusionSession=null;home();}carousel.removeCallbacks(tick);if(homeCanvas&&heroes.length()>1)carousel.postDelayed(tick,7000);}
 @Override protected void onPause(){if(heroSwipe!=null)heroSwipe.cancel();resumed=false;carousel.removeCallbacks(tick);if(body!=null)Skeleton.pause(body);super.onPause();}
 @Override public void onDestroy(){if(heroSwipe!=null)heroSwipe.dispose();carousel.removeCallbacksAndMessages(null);super.onDestroy();}
 @Override public void onSaveInstanceState(Bundle b){b.putBoolean("cinema.settings","我的".equals(HomeRules.navAlias(selectedTab))||"设置".equals(selectedTab));if(scroll!=null)b.putInt("home.scrollY",scroll.getScrollY());super.onSaveInstanceState(b);}
